const assets = new Map<string, BrandAsset>([["/assets/9to1-logo.png",{"sha256":"1f4bb0b9175b26d5c636d3b12811a9964bcebfaa7fff0a2859ceaa1599893d36","contentType":"image/png","length":57734,"base64":""}],["/assets/cakemods-logo.png",{"sha256":"18d9d61c710955b90728271d7678cd67ddce26bc5537b6ea3052319bb27a6378","contentType":"image/png","length":605554,"base64":""}],["/assets/fonts/montserrat-latin-ext-italic.woff2",{"sha256":"9f7c3dc0c1fdbc8b09d53d1beb4aca048a5aff376ac5423878e03e83e89a7fe8","contentType":"font/woff2","length":74892,"base64":""}],["/assets/fonts/montserrat-latin-italic.woff2",{"sha256":"0eb22e3d769a66a92dbd82e3aefa5740e5bc21afa4485f62f92b22656d49182a","contentType":"font/woff2","length":39632,"base64":""}],["/assets/fonts/montserrat-latin-ext-normal.woff2",{"sha256":"54d9a78b7ff60b689ad9f3017ffac8547b5d871afec733f6c1c3ae36577ee504","contentType":"font/woff2","length":70688,"base64":""}],["/assets/fonts/montserrat-latin-normal.woff2",{"sha256":"06b16db7a969135d48d38c49183be7fb88d4452e2a3011957c7851941f4e4879","contentType":"font/woff2","length":37956,"base64":""}],["/assets/fonts/OFL-Montserrat.txt",{"sha256":"8b7141c03fa4f8d44e6345d5d4931709290f0f67875e452e95ac1fd3a027802e","contentType":"text/plain; charset=utf-8","length":4400,"base64":""}]]);
const decodedAssets = new Map<string, ArrayBuffer>();

function assetResponse(request: Request, asset: BrandAsset): Response {
  if (request.method !== 'GET' && request.method !== 'HEAD') {
    return new Response(null, { status: 405, headers: { allow: 'GET, HEAD', 'cache-control': 'no-store' } });
  }
  const versions = new URL(request.url).searchParams.getAll('v');
  const versioned = versions.length === 1 && versions[0] === asset.sha256;
  let body: ArrayBuffer | null = null;
  if (request.method === 'GET') {
    if (!decodedAssets.has(asset.sha256)) {
      decodedAssets.set(asset.sha256, Uint8Array.from(atob(asset.base64), character => character.charCodeAt(0)).buffer);
    }
    body = decodedAssets.get(asset.sha256)!;
  }
  return new Response(body, { headers: {
    'content-type': asset.contentType,
    'content-length': String(asset.length),
    'cache-control': versioned ? 'public, max-age=31536000, immutable' : 'public, max-age=300',
    'x-content-type-options': 'nosniff',
  } });
}

// Return null for every unknown path so the parent router remains authoritative.
export function brandAssetResponse(request: Request): Response | null {
  const asset = assets.get(new URL(request.url).pathname);
  return asset ? assetResponse(request, asset) : null;
}

// Preserve the original helper contract for existing 9to1 logo callers.
export function nineLogoResponse(request: Request): Response {
  return assetResponse(request, assets.get('/assets/9to1-logo.png')!);
}
